const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');
class Node {constructor(tag){this.tag=tag;this.children=[];this.attrs={};this._text='';}set textContent(v){this._text=String(v);this.children=[];}get textContent(){return this._text+this.children.map(n=>n.textContent).join('');}append(...items){for(const n of items){if(n.parent)n.remove();n.parent=this;this.children.push(n);}}replaceChildren(...items){for(const n of this.children)n.parent=null;this.children=[];this._text='';this.append(...items);}remove(){if(this.parent){this.parent.children=this.parent.children.filter(n=>n!==this);this.parent=null;}}get parentNode(){return this.parent;}setAttribute(k,v){this.attrs[k]=String(v);}getAttribute(k){return this.attrs[k];}}
const roots=new Map(),document={createElement:t=>new Node(t),createElementNS:(_,t)=>new Node(t),getElementById:id=>{if(!roots.has(id))roots.set(id,new Node('div'));return roots.get(id);}};
let now=1000000,calls=[],queue=[];const context=vm.createContext({document,Date:class extends Date {static now(){return now;}},console,setInterval:()=>{},fetch:async url=>{calls.push(url);if(!queue.length)throw Error('offline');const q=queue.shift();if(q instanceof Error)throw q;return {ok:q.ok!==false,json:async()=>q.body};}});
const page=fs.readFileSync(process.argv[2],'utf8');vm.runInContext(page.match(/<script>([\s\S]*?)<\/script>/)[1].replace('start();',''),context);
const run=s=>vm.runInContext(s,context);
run('ingestEvents({events:[]})');assert.equal(roots.get('events').textContent,'No events yet.');assert.equal(run('liveStatus(29.9)'),'LIVE');assert.equal(run('liveStatus(30)'),'DELAYED');assert.equal(run('liveStatus(180)'),'STALE');
run(`render({generated_at_ms:1000000,heartbeat_ms:1000000,tick_age_s:2,equity:10000,watchlist:{core:[{symbol:'<img onerror=evil>',direction:'LONG',score:71,score_parts:[{code:'OSCILLATION',value:18.4,points:27.6},{code:'LIQUIDITY_SPREAD',value:.08,points:3.5}]}],bench:[]},open_bots:[{bot_id:1,symbol:'RAY',direction:'LONG',range_low:1,range_high:2,price:1.5,opened_ms:0,net:2}],closed_bots:[],groups:{},equity_curve:[[0,9990],[1000000,10000]]},false)`);
assert(roots.get('core').textContent.includes('<img onerror=evil>'));assert(roots.get('core').textContent.includes('18.4 expected grids/h'));
const before=run('botNodes.get(1).node');run('render(lastReport,false)');assert.equal(run('botNodes.get(1).node'),before);
now+=180000;run('refreshStatus()');assert.equal(roots.get('health').textContent,'STALE');
run('render({...lastReport,published_at_ms:1000000},true)');assert(roots.get('health').textContent.includes('snapshot, published 3 min ago'));
(async()=>{queue=[{body:{...run('lastReport'),generated_at_ms:now}},{body:{events:[{ts_ms:100,event_id:1,type:'FILL',symbol:'RAY',bot_id:1},{ts_ms:100,event_id:2,type:'GRID',symbol:'RAY',bot_id:1}]}}];await run('poll()');assert.equal(calls.at(-1),'/api/events?since=0');assert.equal(run('eventRows.length'),2);queue=[{body:run('lastReport')},{body:{events:[{ts_ms:100,event_id:1,type:'FILL',symbol:'RAY',bot_id:1},{ts_ms:100,event_id:2,type:'GRID',symbol:'RAY',bot_id:1}]}}];await run('poll()');assert.equal(calls.at(-1),'/api/events?since=100&after_event_id=2');assert.equal(run('eventRows.length'),2);
queue=[Error('local offline'),{body:{...run('lastReport'),published_at_ms:now}}];await run('poll()');assert.equal(calls.at(-1),'/data/autopilot.json');assert(roots.get('health').textContent.includes('snapshot'));
queue=[{body:run('lastReport')},{body:{events:Array.from({length:80},(_,i)=>({ts_ms:200+i,type:'FILL',symbol:'RAY',bot_id:1}))}}];await run('poll()');assert.equal(run('eventRows.length'),50);now+=300000;queue=[{body:{...run('lastReport'),tick_age_s:1,generated_at_ms:now-300000}},{body:{events:[]}}];await run('poll()');assert.equal(roots.get('health').textContent,'STALE');assert.equal(run('Object.keys(PARTS).length'),11);queue=[{body:run('lastReport')},{body:{events:Array.from({length:500},(_,i)=>({ts_ms:1000,event_id:i+1,type:'FILL',symbol:'RAY',bot_id:1}))}}];await run('poll()');queue=[{body:run('lastReport')},{body:{events:[{ts_ms:1000,event_id:501,type:'GRID',symbol:'RAY',bot_id:1},{ts_ms:1001,event_id:502,type:'FILL',symbol:'RAY',bot_id:1}]}}];await run('poll()');assert.equal(calls.at(-1),'/api/events?since=1000&after_event_id=500');assert.equal(run('eventCursor'),1001);assert.equal(run('eventCursorId'),502);assert.equal(run('eventRows.at(-2).e.event_id'),501);console.log('Paper dashboard behavior passed');})().catch(e=>{console.error(e);process.exitCode=1;});
